import {$,readStore,writeStore,overlaps,validSlot,uid,escapeHTML as esc,download} from './core.js';
let slots=readStore('swa-slots-v1',[]);if(!Array.isArray(slots))slots=[];const today=new Date(),localDate=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;
$('#app').innerHTML=`<div class="grid two"><div class="panel"><h2>Plan an appointment</h2><form id="booking" class="stack"><label>Appointment title<input name="title" required maxlength="120" placeholder="e.g. Project discovery call"></label><label>Date<input name="date" type="date" required value="${localDate}"></label><div class="grid two"><label>Start<input name="start" type="time" required value="09:00"></label><label>End<input name="end" type="time" required value="09:30"></label></div><label>Notes<textarea name="notes" maxlength="500" placeholder="Agenda or meeting details"></textarea></label><button>Save appointment +</button></form><p class="small">Times use your local wall clock. Appointments must start and end on the same day.</p></div><div class="panel"><div class="row"><h2>Your agenda</h2><button id="export" class="secondary">Export .ics ↓</button></div><label>Filter by date<input id="filter" type="date"></label><button class="secondary" id="all" style="margin:12px 0">Show all dates</button><div id="agenda"></div></div></div>`;
function render(){const filtered=slots.filter(s=>!$('#filter').value||s.date===$('#filter').value).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));$('#agenda').innerHTML=filtered.length?filtered.map(s=>`<article class="session"><span class="badge">${esc(s.date)} · ${esc(s.start)}–${esc(s.end)}</span><h2>${esc(s.title)}</h2><p class="small">${esc(s.notes)}</p><button class="danger" data-delete="${esc(s.id)}">Delete appointment</button></article>`).join(''):'<p class="empty">No appointments for this view.</p>'}
$('#booking').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.title=d.title.trim();if(!d.title||!validSlot(d)){$('#status').textContent='Add a title and make sure the end time is after the start time.';return}if(slots.some(s=>overlaps(s,d))){$('#status').textContent='That time overlaps an existing appointment. Choose another slot.';return}slots.push({...d,id:uid()});writeStore('swa-slots-v1',slots);e.currentTarget.reset();render();$('#status').textContent='Appointment saved on this device.'};$('#filter').onchange=render;$('#all').onclick=()=>{$('#filter').value='';render()};$('#agenda').onclick=e=>{if(e.target.dataset.delete){slots=slots.filter(s=>s.id!==e.target.dataset.delete);writeStore('swa-slots-v1',slots);render();$('#status').textContent='Appointment deleted.'}};
const escapeICS=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;').replace(/\r/g,'');
function fold(line){let out=[],chunk='',bytes=0;for(const char of line){let size=new TextEncoder().encode(char).length;if(bytes+size>73){out.push(chunk);chunk=' ';bytes=1}chunk+=char;bytes+=size}out.push(chunk);return out.join('\r\n')}
$('#export').onclick=()=>{if(!slots.length){$('#status').textContent='Add an appointment before exporting.';return}const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Seloana Web Architects//Slotwise//EN','CALSCALE:GREGORIAN',...slots.flatMap(s=>['BEGIN:VEVENT',`UID:${s.id}@slotwise.local`,`DTSTAMP:${stamp}`,`DTSTART:${s.date.replace(/-/g,'')}T${s.start.replace(':','')}00`,`DTEND:${s.date.replace(/-/g,'')}T${s.end.replace(':','')}00`,`SUMMARY:${escapeICS(s.title)}`,`DESCRIPTION:${escapeICS(s.notes)}`,'END:VEVENT']),'END:VCALENDAR'];download('slotwise-agenda.ics',lines.map(fold).join('\r\n')+'\r\n','text/calendar');$('#status').textContent='Calendar exported with local floating times.'};render();
